#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk.Web #:package Carter@7.0.0 #:package Microsoft.Extensions.Caching.StackExchangeRedis@8.0.0 #:package Microsoft.Extensions.Caching.Memory@8.0.0 #:package System.Threading.Channels@8.0.0 #:package Microsoft.DotNet.ILCompiler@8.0.0 #:package System.Text.Json@8.0.0 #:property PublishAot=true #:property IlcGenerateCompleteTypeMetadata false #:property IlcOptimizationPreference Speed #:property IlcInvariantGlobalization true #:property LangVersion=preview #:property TargetFramework=net11.0 #:property Nullable=enable #:property ImplicitUsings=enable #:property PublishAot=true  using System.Threading.Channels; using Microsoft.Extensions.ObjectPool; using Carter; using System.Security.Claims; using Microsoft.Extensions.Caching.Distributed; using Microsoft.Extensions.Caching.Memory; using System.Text; using System.Reflection; using Microsoft.Extensions.DependencyInjection;  [LibraryImport("kernel32.dll", StringMarshalling = StringMarshalling.Utf8)] internal static partial nint LoadLibrary(string lpLibFileName);  // 使用UnmanagedCallersOnly特性标记本地方法 [UnmanagedCallersOnly(EntryPoint = "NativeCallback")] public static int NativeCallback(int value) => value * 2;  // 在模块启动时预先收集所有需要的类型 [ModuleInitializer] public static void InitializeAot() {     // 使用DynamicDependency确保AOT编译包含所需类型     DynamicDependency.LoadAssemblyTypes(         typeof(Program).Assembly,         typeof(JsonSerializerOptions),         typeof(HttpClient));          // 注册JSON序列化上下文     JsonSerializerOptions.Default.TypeInfoResolverChain.Add(         JsonContext.Default); }  // 使用源生成器创建JSON上下文 [JsonSerializable(typeof(MyModel))] internal partial class JsonContext : JsonSerializerContext { }  // 1. 模块接口定义 public interface ICarterModule {     string ModuleName { get; }     Task InitializeAsync();     Task ExecuteAsync(RouteRequest request); }  // 2. 抽象模块基类(CPU cache-line对齐) [SkipLocalsInit] public abstract class CarterModuleBase : CarterModule, ICarterModule {     private readonly Channel<RouteRequest> _requestChannel;     private readonly ObjectPool<RouteContext> _contextPool;     private readonly TailLatencyOptimizer _latencyOptimizer;     private readonly IDistributedCache _distributedCache;     private readonly IMemoryCache _memoryCache;     private readonly MemoryCacheEntryOptions _memoryCacheOptions;      public string ModuleName => GetType().Name;      protected CarterModuleBase(         IDistributedCache cache,         IMemoryCache memoryCache,         string basePath = "") : base(basePath)     {         _distributedCache = distributedCache;         _memoryCache = memoryCache;         _latencyOptimizer = new TailLatencyOptimizer();                  _memoryCacheOptions = new MemoryCacheEntryOptions()             .SetSize(1)  // 每个缓存项大小             .SetSlidingExpiration(TimeSpan.FromSeconds(30))             .SetPostEvictionCallback((key, value, reason, state) =>             {                 // 缓存淘汰时的回调                 var logger = ctx.RequestServices.GetService<ILogger<CarterModuleBase>>();                 logger?.LogInformation($"Cache evicted: Key={key}, Reason={reason}");                                  // 如果是主动删除，则不处理                 if (reason == EvictionReason.Removed) return;                                  // 其他情况可以添加自定义处理逻辑                 // 例如：记录到监控系统或触发缓存预热             });         // Disruptor模式通道配置         _requestChannel = Channel.CreateBounded<RouteRequest>(new BoundedChannelOptions(10000)         {             SingleReader = true,             AllowSynchronousContinuations = true,             FullMode = BoundedChannelFullMode.DropOldest         });          // 上下文对象池         _contextPool = new DefaultObjectPool<RouteContext>(             new RouteContextPooledPolicy(), 1000);     }      // 2. 高性能路由注册(Span优化)     [MethodImpl(MethodImplOptions.AggressiveOptimization)]     protected void MapGet<T>(string pattern, Func<HttpContext, Task<T>> handler)     {         base.MapGet(pattern, async ctx =>         {             var cacheKey = $"route:{ctx.Request.Path}";             var cached = await _cache.GetAsync(cacheKey);             if (cached != null)             {                 await ctx.Response.WriteAsync(Encoding.UTF8.GetString(cached.Span));                 return;             }              var request = new RouteRequest(ctx);             await _requestChannel.Writer.WriteAsync(request);             var result = await request.CompletionSource.Task;                          await _cache.SetAsync(cacheKey,                  Encoding.UTF8.GetBytes(result.ToString()),                 new DistributedCacheEntryOptions                 {                     AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5)                 });                          await ctx.Response.WriteAsJsonAsync(result);         });     }      // 2. 高性能路由注册扩展(Span优化)     [MethodImpl(MethodImplOptions.AggressiveOptimization)]     protected void MapPost<TRequest, TResponse>(string pattern, Func<HttpContext, TRequest, Task<TResponse>> handler)     {         base.MapPost(pattern, async ctx =>         {             var cacheKey = $"route:{ctx.Request.Path}";                          // 1. 检查本地缓存             if (_memoryCache.TryGetValue(cacheKey, out TResponse cachedValue))             {                 await ctx.Response.WriteAsJsonAsync(cachedValue);                 return;             }              // 2. 处理请求             var request = await ctx.Request.ReadFromJsonAsync<TRequest>();             var response = await handler(ctx, request!);                          // 3. 更新两级缓存             var bytes = JsonSerializer.SerializeToUtf8Bytes(response);             await _distributedCache.SetAsync(cacheKey, bytes, new DistributedCacheEntryOptions             {                 AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5)             });             _memoryCache.Set(cacheKey, response, _memoryCacheOptions);                          await ctx.Response.WriteAsJsonAsync(response);         });     }      [MethodImpl(MethodImplOptions.AggressiveOptimization)]     protected void MapPut<TRequest, TResponse>(string pattern, Func<HttpContext, TRequest, Task<TResponse>> handler)     {         base.MapPut(pattern, async ctx =>         {             var cacheKey = $"route:{ctx.Request.Path}";             var request = await ctx.Request.ReadFromJsonAsync<TRequest>();             var response = await handler(ctx, request!);                          // 更新两级缓存             var bytes = JsonSerializer.SerializeToUtf8Bytes(response);             await _distributedCache.SetAsync(cacheKey, bytes, new DistributedCacheEntryOptions             {                 AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5)             });             _memoryCache.Set(cacheKey, response, _memoryCacheOptions);                          await ctx.Response.WriteAsJsonAsync(response);         });     }      [MethodImpl(MethodImplOptions.AggressiveOptimization)]     protected void MapDelete<T>(string pattern, Func<HttpContext, Task<T>> handler)     {         base.MapPatch(pattern, async ctx =>         {             var cacheKey = $"route:{ctx.Request.Path}";             var request = await ctx.Request.ReadFromJsonAsync<TRequest>();             var response = await handler(ctx, request!);                          // 更新两级缓存             var bytes = JsonSerializer.SerializeToUtf8Bytes(response);             await _distributedCache.SetAsync(cacheKey, bytes, new DistributedCacheEntryOptions             {                 AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5)             });             _memoryCache.Set(cacheKey, response, _memoryCacheOptions);                          await ctx.Response.WriteAsJsonAsync(response);         });     }      [MethodImpl(MethodImplOptions.AggressiveOptimization)]     protected void MapPatch<TRequest, TResponse>(string pattern, Func<HttpContext, TRequest, Task<TResponse>> handler)     {         base.MapDelete(pattern, async ctx =>         {             var cacheKey = $"route:{ctx.Request.Path}";             var response = await handler(ctx);                          // 删除两级缓存             await _distributedCache.RemoveAsync(cacheKey);             _memoryCache.Remove(cacheKey);                          await ctx.Response.WriteAsJsonAsync(response);         });     }      // 3. 后台路由处理     protected override async Task ExecuteAsync(CancellationToken stoppingToken)     {         await foreach (var request in _requestChannel.Reader.ReadAllAsync(stoppingToken))         {             var context = _contextPool.Get();             try             {                 await context.ProcessAsync(request);                 _latencyOptimizer.RecordLatency();             }             finally             {                 _contextPool.Return(context);             }         }     }      // 3. 程序集批量注册扩展     public static class CarterModuleExtensions     {         public static IServiceCollection AddCarterModules(this IServiceCollection services,              params Assembly[] assemblies)         {             if (assemblies.Length == 0)             {                 assemblies = AppDomain.CurrentDomain.GetAssemblies();             }              foreach (var assembly in assemblies)             {                 var moduleTypes = assembly.GetTypes()                     .Where(t => typeof(ICarterModule).IsAssignableFrom(t) && !t.IsAbstract);                  foreach (var type in moduleTypes)                 {                     services.AddTransient(typeof(ICarterModule), type);                 }             }              return services;         }         // 加载指定目录下的DLL文件         public static IServiceCollection AddCarterModulesFromDlls(this IServiceCollection services, string directoryPath)         {             var dlls = Directory.GetFiles(directoryPath, "*.dll");             foreach (var dll in dlls)             {                 var assembly = AssemblyLoadContext.Default.LoadFromAssemblyPath(dll);                 services.AddCarterModules(assembly);             }             return services;         }     }      // 4. 模块注册器(高性能实现) [SkipLocalsInit] public sealed class CarterModuleRegistry {     private readonly Dictionary<string, ICarterModule> _modules = new();     private readonly ReaderWriterLockSlim _lock = new();      public void RegisterModule(ICarterModule module)     {         _lock.EnterWriteLock();         try         {             _modules[module.ModuleName] = module;         }         finally         {             _lock.ExitWriteLock();         }     }      public ICarterModule GetModule(string moduleName)     {         _lock.EnterReadLock();         try         {             return _modules.TryGetValue(moduleName, out var module)                  ? module                  : null;         }         finally         {             _lock.ExitReadLock();         }     } }  // 5. DLL动态加载能力实现 public interface IPluginLoader {     IEnumerable<ICarterModule> LoadModulesFromDll(string dllPath);     void WatchForChanges(string directory, Action<ICarterModule> onModuleChanged); }  // 装饰器模式增强模块系统 public class DecoratedCarterModule : ICarterModule {     private readonly ICarterModule _innerModule;     private readonly ILogger<DecoratedCarterModule> _logger;      public string ModuleName => _innerModule.ModuleName;      public DecoratedCarterModule(ICarterModule innerModule, ILogger<DecoratedCarterModule> logger)     {         _innerModule = innerModule;         _logger = logger;     }      public Task InitializeAsync()     {         _logger.LogInformation($"Initializing module {ModuleName}");         return _innerModule.InitializeAsync();     }      public Task ExecuteAsync(RouteRequest request)     {         _logger.LogInformation($"Executing module {ModuleName}");         return _innerModule.ExecuteAsync(request);     } }  // 模块外观类 public class ModuleFacade : IDisposable {     private readonly IPluginLoader _pluginLoader;     private readonly IServiceProvider _serviceProvider;     private readonly CarterModuleRegistry _registry;     private readonly List<FileSystemWatcher> _watchers = new();      public ModuleFacade(IPluginLoader pluginLoader, IServiceProvider serviceProvider)     {         _pluginLoader = pluginLoader;         _serviceProvider = serviceProvider;         _registry = new CarterModuleRegistry();     }      public void LoadModulesFromDirectory(string directory)     {         foreach (var dll in Directory.GetFiles(directory, "*.dll"))         {             var modules = _pluginLoader.LoadModulesFromDll(dll);             foreach (var module in modules)             {                 _registry.RegisterModule(module);             }         }                  // 设置文件监视         var watcher = new FileSystemWatcher(directory, "*.dll")         {             EnableRaisingEvents = true,             NotifyFilter = NotifyFilters.LastWrite         };         watcher.Changed += (sender, e) =>          {             var module = _pluginLoader.LoadModulesFromDll(e.FullPath).FirstOrDefault();             if (module != null)             {                 _registry.RegisterModule(module);             }         };         _watchers.Add(watcher);     }      public ICarterModule GetModule(string name) => _registry.GetModule(name);      public void Dispose()     {         foreach (var watcher in _watchers)         {             watcher.Dispose();         }     } }  // 默认插件加载器实现 public class DefaultPluginLoader : IPluginLoader {     private readonly IServiceProvider _serviceProvider;      public DefaultPluginLoader(IServiceProvider serviceProvider)     {         _serviceProvider = serviceProvider;     }      public IEnumerable<ICarterModule> LoadModulesFromDll(string dllPath)     {         var assembly = Assembly.LoadFrom(dllPath);         return assembly.GetTypes()             .Where(t => typeof(ICarterModule).IsAssignableFrom(t) && !t.IsAbstract)             .Select(t => (ICarterModule)ActivatorUtilities.CreateInstance(_serviceProvider, t));     }      public void WatchForChanges(string directory, Action<ICarterModule> onModuleChanged)     {         var watcher = new FileSystemWatcher(directory, "*.dll")         {             EnableRaisingEvents = true,             NotifyFilter = NotifyFilters.LastWrite         };         watcher.Changed += (sender, e) =>          {             var module = LoadModulesFromDll(e.FullPath).FirstOrDefault();             if (module != null)             {                 onModuleChanged?.Invoke(module);             }         };     } } }  // 4. 示例模块实现 public class UserModule : CarterModuleBase {     public UserModule(IDistributedCache cache) : base(cache, "/api/users")     {         MapGet("/{id}", GetUserById);         MapPost<UserCreateRequest, User>("", CreateUser);         MapPut<UserUpdateRequest, User>("/{id}", UpdateUser);         MapDelete<User>("/{id}", DeleteUser);     }      private async Task<User> GetUserById(HttpContext ctx)     {         var userId = ctx.Request.RouteValues["id"]?.ToString();         return new User { Id = userId, Name = "Test User" };     }      private async Task<User> CreateUser(HttpContext ctx, UserCreateRequest request)     {         return new User { Id = Guid.NewGuid().ToString(), Name = request.Name };     }      private async Task<User> UpdateUser(HttpContext ctx, UserUpdateRequest request)     {         var userId = ctx.Request.RouteValues["id"]?.ToString();         return new User { Id = userId, Name = request.Name };     }      private async Task<User> DeleteUser(HttpContext ctx)     {         var userId = ctx.Request.RouteValues["id"]?.ToString();         return new User { Id = userId, Name = "Deleted User" };     } }  // 新增请求记录类型 public record UserCreateRequest(string Name); public record UserUpdateRequest(string Name); // 辅助记录类型 public record User(string Id, string Name); public record RouteRequest(HttpContext Context, TaskCompletionSource<object> CompletionSource = null!) {     public RouteRequest(HttpContext context) : this(context, new TaskCompletionSource<object>())     {     } }  // 1. 添加缓存健康检查端点 public class CacheHealthEndpoint : ICarterModule {     public void AddRoutes(IEndpointRouteBuilder app)     {         app.MapGet("/health/cache", async (IDistributedCache cache, IMemoryCache memoryCache) =>         {             var cacheKey = $"healthcheck:{Guid.NewGuid()}";             try             {                 // 测试分布式缓存                 await cache.SetAsync(cacheKey, Encoding.UTF8.GetBytes("test"),                      new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromSeconds(1) });                                  // 测试内存缓存                 memoryCache.Set(cacheKey, "test", TimeSpan.FromSeconds(1));                                  return Results.Ok(new { Status = "Healthy" });             }             catch (Exception ex)             {                 return Results.Problem(detail: ex.Message);             }         }).WithTags("Health");     } }  // 2. 添加性能监控中间件 [SkipLocalsInit] public class PerformanceMonitoringMiddleware {     private readonly RequestDelegate _next;     private readonly TailLatencyOptimizer _latencyOptimizer;      public PerformanceMonitoringMiddleware(RequestDelegate next, TailLatencyOptimizer latencyOptimizer)     {         _next = next;         _latencyOptimizer = latencyOptimizer;     }      [MethodImpl(MethodImplOptions.AggressiveOptimization)]     public async Task InvokeAsync(HttpContext context)     {         var stopwatch = Stopwatch.StartNew();         try         {             await _next(context);         }         finally         {             stopwatch.Stop();             _latencyOptimizer.RecordLatency(stopwatch.ElapsedTicks);         }     } }  // 3. 主程序配置更新 var builder = WebApplication.CreateBuilder(args);  // 添加性能监控服务 builder.Services.AddSingleton<TailLatencyOptimizer>(); builder.Services.AddSingleton<PerformanceMonitoringMiddleware>();  builder.Services.Scan(scan => scan     .FromAssemblies(AssemblyLoadContext.Default.LoadFromAssemblyPath(dllPath))     .AddClasses(classes => classes.AssignableTo<IService>())     .AsImplementedInterfaces()     .WithScopedLifetime());  // 在Program.cs中 builder.Services     .AddCarterModulesFromDlls("Plugins")     .Scan(scan => scan         .FromAssemblies(AssemblyLoadContext.Default.LoadFromAssemblyPath("Plugins/MyService.dll"))         .AddClasses()         .AsMatchingInterface());  // 配置Redis缓存 builder.Services.AddStackExchangeRedisCache(options => {     options.Configuration = builder.Configuration.GetConnectionString("Redis");     options.InstanceName = "Carter:"; });  // 自动注册所有Carter模块 builder.Services.AddCarterModules(typeof(Program).Assembly); builder.Services.AddCarter(configurator: options => {     options.WithModule<UserModule>();     // 其他模块... });  // 添加新模块 builder.Services     .AddDistributedTracing()     .AddCarterApiDocs()     .AddSingleton<CarterMetrics>();  var app = builder.Build();  // 使用性能监控中间件 app.UseMiddleware<PerformanceMonitoringMiddleware>(); // 使用Swagger app.UseSwagger(); app.UseSwaggerUI(); // 注册健康检查端点 app.MapCarter(); new CacheHealthEndpoint().AddRoutes(app);  app.Run();  // 在CarterIntegration类中添加AOT优化配置 [assembly: System.Runtime.CompilerServices.DisableRuntimeMarshalling] [assembly: System.Runtime.Versioning.RequiresPreviewFeatures]  public static class CarterIntegration {     // 优化P/Invoke调用     [LibraryImport("libc", EntryPoint = "rand")]     [UnmanagedCallersOnly]     private static partial int rand();      // 反射优化 - 使用DynamicDependency特性     [DynamicDependency(DynamicallyAccessedMemberTypes.All, typeof(ProductModule))]     [DynamicDependency(DynamicallyAccessedMemberTypes.All, typeof(CarterModuleBase))]          // 添加Json源生成器支持     [JsonSerializable(typeof(ProductModule))]     [JsonSerializable(typeof(CarterModuleBase))]     private partial class CarterJsonContext : JsonSerializerContext {}      public static WebApplication CreateApplication(string[] args)     {         var builder = WebApplication.CreateSlimBuilder(args);          // 配置AOT优化选项         builder.Services.ConfigureHttpJsonOptions(options =>         {             options.SerializerOptions.TypeInfoResolver = CarterJsonContext.Default;         });          // ... existing code ...          // 生产级AOT配置         if (builder.Environment.IsProduction())         {             // 启用AggressiveOptimization             RuntimeHelpers.EnsureSufficientExecutionStack();                          // 配置内存池             builder.Services.AddSingleton<MemoryPool<byte>>(sp =>                  new SlabMemoryPool(SlabMemoryPool.DefaultMaximumBufferSize));                              // 配置线程池             ThreadPool.SetMinThreads(Environment.ProcessorCount * 2, Environment.ProcessorCount * 2);         }          // ... existing code ...     } }  // 添加内存池实现 internal sealed class SlabMemoryPool : MemoryPool<byte> {     public static readonly int DefaultMaximumBufferSize = 1024 * 1024; // 1MB          public SlabMemoryPool(int maximumBufferSize)     {         MaxBufferSize = maximumBufferSize;     }          public override int MaxBufferSize { get; }          public override IMemoryOwner<byte> Rent(int minBufferSize = -1)     {         if (minBufferSize == -1) minBufferSize = MaxBufferSize;         return new SlabMemoryOwner(minBufferSize);     }          protected override void Dispose(bool disposing) { } }  internal sealed class SlabMemoryOwner : IMemoryOwner<byte> {     private byte[] _array;          public SlabMemoryOwner(int size)     {         _array = ArrayPool<byte>.Shared.Rent(size);     }          public Memory<byte> Memory => _array;          public void Dispose()     {         if (_array != null)         {             ArrayPool<byte>.Shared.Return(_array);             _array = null;         }     } }  // 多租户支持 public class TenantContext {     public string TenantId { get; set; }     public bool IsValid { get; set; } }  public static class TenantMiddleware {     public static IApplicationBuilder UseTenantRouting(this IApplicationBuilder app)     {         return app.Use(async (context, next) =>         {             var tenantId = context.Request.Headers["X-Tenant-ID"].FirstOrDefault();             context.Items["TenantContext"] = new TenantContext             {                 TenantId = tenantId ?? "default",                 IsValid = !string.IsNullOrEmpty(tenantId)             };             await next();         });     } }  // 尾延迟优化器集成 public static class TailLatencyOptimizerExtensions {     public static IServiceCollection AddTailLatencyOptimizer(this IServiceCollection services)     {         services.AddSingleton<TailLatencyOptimizer>();         return services;     } }  // 安全增强 public static class SecurityMiddleware {     public static IApplicationBuilder UseRequestValidation(this IApplicationBuilder app)     {         return app.Use(async (context, next) =>         {             // 请求验证逻辑             if (!IsValidRequest(context))             {                 context.Response.StatusCode = 400;                 await context.Response.WriteAsync("Invalid request");                 return;             }             await next();         });     }      private static bool IsValidRequest(HttpContext context)     {         // 实现请求验证逻辑         return true;     } }  // 速率限制 public static class RateLimitingMiddleware {     public static IApplicationBuilder UseRateLimiting(this IApplicationBuilder app)     {         var rateLimiter = new RateLimiter(new RateLimiterOptions         {             PermitLimit = 100,             Window = TimeSpan.FromMinutes(1)         });          return app.Use(async (context, next) =>         {             if (!await rateLimiter.AcquireAsync())             {                 context.Response.StatusCode = 429;                 await context.Response.WriteAsync("Too many requests");                 return;             }             await next();         });     } }  // 在CarterIntegration类中集成这些功能 public static class CarterIntegration {     public static WebApplication CreateApplication(string[] args)     {         var builder = WebApplication.CreateBuilder(args);          // 添加多租户支持         builder.Services.AddSingleton<IMemoryCache>(new MemoryCache(new MemoryCacheOptions()));                  // 添加尾延迟优化器         builder.Services.AddTailLatencyOptimizer();          var app = builder.Build();          // 使用中间件         app.UseTenantRouting();         app.UseRequestValidation();         app.UseRateLimiting();          // 其他模块...     } }  // ... existing code ...
